CREATE OR REPLACE FUNCTION public.create_sale_receivable() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.payments(company_id,sale_id,kind,amount,status) VALUES(NEW.company_id,NEW.id,'plate',NEW.amount,'pending'); RETURN NEW; END $$;
CREATE TRIGGER sale_receivable AFTER INSERT ON public.sales FOR EACH ROW EXECUTE FUNCTION public.create_sale_receivable();
CREATE OR REPLACE FUNCTION public.prepare_new_sale() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.cost:=0; IF NEW.amount<=0 OR NEW.payment_status<>'pending' THEN RAISE EXCEPTION 'Nova venda exige valor positivo e recebimento pendente.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER new_sale_rules BEFORE INSERT ON public.sales FOR EACH ROW EXECUTE FUNCTION public.prepare_new_sale();
CREATE OR REPLACE FUNCTION public.activate_registered_plate(_code text,_company_name text,_review_url text,_contact jsonb,_accepted boolean,_annual_price numeric) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; configured numeric; company_uuid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Acesso negado.'; END IF; SELECT subscription_price INTO configured FROM public.settings WHERE id=true FOR SHARE; IF _accepted IS DISTINCT FROM true OR _annual_price IS DISTINCT FROM configured THEN RAISE EXCEPTION 'Confirme o aceite do valor anual atual.'; END IF; IF jsonb_typeof(_contact)<>'object' OR octet_length(_contact::text)>3000 OR coalesce(_contact->>'whatsapp','')='' OR coalesce(_contact->>'document','')='' OR coalesce(_contact->>'street','')='' OR coalesce(_contact->>'city','')='' THEN RAISE EXCEPTION 'Complete os dados de cadastro.'; END IF; result:=public.activate_plate(_code,_company_name,nullif(_review_url,'')); company_uuid:=(result->>'companyId')::uuid; UPDATE public.companies SET contact=_contact WHERE id=company_uuid AND owner_id=auth.uid(); UPDATE public.plates SET annual_consent_at=now(),annual_consent_version='2026-11-13',annual_consent_amount=configured WHERE qr_code=_code; RETURN result; END $$;